package com.example.governance.dataobject;

import com.example.governance.security.AuditLog;
import java.util.*;
import org.springframework.http.*;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

@RestController
public class ObjectController {
    record DirectoryInput(String name,Long parentId) {}
    record SortRequest(List<com.example.governance.common.DirectorySorter.Item> items) {}
    record Registration(long directoryId,ObjectStore.Identity identity,String name,String description) {}
    record BatchRequest(List<Registration> objects) {}
    record Result(ObjectStore.Identity identity,boolean success,Long objectId,String error) {}
    record Detail(ObjectStore.Item object,List<ObjectStore.Field> fields) {}
    record UpdateInput(long directoryId,String name,String description,long version) {}
    record BindInput(Long datasetId) {}
    record PreviewInput(List<String> fields,int limit) {}
    private final ObjectStore store;private final ObjectMetadata metadata;private final AuditLog audit;private final ObjectExecutionService execution;private final ObjectPreviewService preview;private final ObjectSchemaService schema;
    public ObjectController(ObjectStore store,ObjectMetadata metadata,AuditLog audit,ObjectExecutionService execution,ObjectPreviewService preview,ObjectSchemaService schema){this.store=store;this.metadata=metadata;this.audit=audit;this.execution=execution;this.preview=preview;this.schema=schema;}
    private static void require(Authentication auth,String permission){if(auth.getAuthorities().stream().noneMatch(a->a.getAuthority().equals(permission)))throw new ResponseStatusException(HttpStatus.FORBIDDEN);}
    @GetMapping("/api/object-directories") public List<ObjectStore.Directory> directories(){return store.directories();}
    @PostMapping("/api/object-directories") public Map<String,Long> createDirectory(@RequestBody DirectoryInput input,Authentication auth){try{long id=store.createDirectory(input.name(),input.parentId());audit.success(auth,"object.directory.create","object_directory",id);return Map.of("id",id);}catch(IllegalArgumentException|IllegalStateException e){audit.failure(auth,"object.directory.create","object_directory","request",e.getMessage());throw e;}}
    @PostMapping("/api/object-directories/sort") public void sortDirectories(@RequestBody SortRequest input,Authentication auth){try{store.sortDirectories(input.items());audit.success(auth,"object.directory.sort","object_directory","tree");}catch(IllegalArgumentException|IllegalStateException e){audit.failure(auth,"object.directory.sort","object_directory","tree",e.getMessage());throw e;}}
    @PutMapping("/api/object-directories/{id}") public void renameDirectory(@PathVariable long id,@RequestBody DirectoryInput input,Authentication auth){try{store.renameDirectory(id,input.name());audit.success(auth,"object.directory.update","object_directory",id);}catch(IllegalArgumentException|IllegalStateException e){audit.failure(auth,"object.directory.update","object_directory",Long.toString(id),e.getMessage());throw e;}}
    @DeleteMapping("/api/object-directories/{id}") public void deleteDirectory(@PathVariable long id,Authentication auth){try{store.deleteDirectory(id);audit.success(auth,"object.directory.delete","object_directory",id);}catch(IllegalArgumentException|IllegalStateException e){audit.failure(auth,"object.directory.delete","object_directory",Long.toString(id),e.getMessage());throw e;}}
    @GetMapping("/api/data-objects") public ObjectStore.Page page(@RequestParam(required=false) Long directoryId,@RequestParam(defaultValue="") String table,@RequestParam(defaultValue="") String name,@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="10") int size){return store.page(directoryId,table,name,page,size);}
    @GetMapping(value="/api/data-objects/export",produces="text/csv;charset=UTF-8") public ResponseEntity<String> export(@RequestParam(required=false) Long directoryId,@RequestParam(defaultValue="") String table,@RequestParam(defaultValue="") String name,Authentication auth){
        try{var first=store.page(directoryId,table,name,1,100);if(first.total()>10000)throw new IllegalArgumentException("导出最多支持 10000 条对象，请缩小查询范围");int exported=0;StringBuilder csv=new StringBuilder("\uFEFF对象名称,对象中文名,数据源编号,数据库,模式,对象类型,字段名,字段类型,长度,精度,可空,主键,注释\r\n");for(int page=1;page<=Math.max(1,(first.total()+99)/100);page++){var result=page==1?first:store.page(directoryId,table,name,page,100);for(var object:result.rows())for(var field:store.fields(object.id())){if(++exported>10000)throw new IllegalArgumentException("导出最多支持 10000 条字段，请缩小查询范围");String[] cells={object.identity().table(),object.name(),Long.toString(object.identity().sourceId()),object.identity().catalog(),object.identity().schema(),object.identity().type(),field.name(),field.type(),Objects.toString(field.length(),""),Objects.toString(field.scale(),""),field.nullable(),field.primaryKey(),field.remarks()};csv.append(Arrays.stream(cells).map(ObjectController::csv).collect(java.util.stream.Collectors.joining(","))).append("\r\n");}}audit.success(auth,"object.export","data_object","export");return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=data-objects.csv").contentType(MediaType.parseMediaType("text/csv;charset=UTF-8")).body(csv.toString());}catch(IllegalArgumentException e){audit.failure(auth,"object.export","data_object","export",e.getMessage());throw e;}
    }
    private static String csv(String input){String value=input==null?"":input;if(!value.isEmpty()&&"=+-@\t\r".indexOf(value.charAt(0))>=0)value="'"+value;return "\""+value.replace("\"","\"\"")+"\"";}
    @GetMapping("/api/data-objects/{id}") public Detail detail(@PathVariable long id){return new Detail(store.find(id),store.fields(id));}
    @PutMapping("/api/data-objects/{id}") public void update(@PathVariable long id,@RequestBody UpdateInput input,Authentication auth){try{store.update(id,input.directoryId(),input.name(),input.description(),input.version());audit.success(auth,"object.update","data_object",id);}catch(IllegalArgumentException|IllegalStateException e){audit.failure(auth,"object.update","data_object",Long.toString(id),e.getMessage());throw e;}}
    @PutMapping("/api/data-objects/{id}/dataset") public void bind(@PathVariable long id,@RequestBody BindInput input,Authentication auth){require(auth,"datasource.dataset.manage_policy");store.bindDataset(id,input.datasetId());audit.success(auth,"object.update","data_object",id);}
    @PostMapping("/api/data-objects/{id}/preview") public List<Map<String,Object>> preview(@PathVariable long id,@RequestBody PreviewInput input,Authentication auth){require(auth,"datasource.query.read");try{if(!(auth.getPrincipal() instanceof com.example.governance.security.AccountPrincipal user))throw new SecurityException();var result=preview.preview(user.id(),id,input.fields(),input.limit());audit.success(auth,"object.preview","data_object",id);return result;}catch(SecurityException e){audit.failure(auth,"object.preview","data_object",Long.toString(id),"无权预览或未配置数据权限");throw new ResponseStatusException(HttpStatus.FORBIDDEN,"未配置数据权限或无权预览");}catch(IllegalArgumentException e){throw e;}catch(Exception e){audit.failure(auth,"object.preview","data_object",Long.toString(id),"预览失败");throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"无法预览数据");}}
    @DeleteMapping("/api/data-objects/{id}") public void delete(@PathVariable long id,Authentication auth){try{store.delete(id);audit.success(auth,"object.delete","data_object",id);}catch(IllegalArgumentException|IllegalStateException e){audit.failure(auth,"object.delete","data_object",Long.toString(id),e.getMessage());throw e;}}
    @GetMapping("/api/data-objects/discovery") public List<ObjectMetadata.Table> discover(@RequestParam long sourceId,@RequestParam(required=false) String catalog,@RequestParam(required=false) String schema,Authentication auth){require(auth,"datasource.source.read");require(auth,"datasource.source.test");try{return metadata.tables(sourceId,catalog,schema);}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"无法读取数据源元数据");}}
    @PostMapping("/api/data-objects/discovery-fields") public List<ObjectStore.Field> discoverFields(@RequestBody ObjectStore.Identity identity,Authentication auth){require(auth,"datasource.source.read");require(auth,"datasource.source.test");try{return metadata.fields(identity);}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"无法读取对象字段");}}
    @PostMapping("/api/data-objects/register") public List<Result> register(@RequestBody BatchRequest input,Authentication auth){require(auth,"datasource.source.read");require(auth,"datasource.source.test");if(input==null||input.objects()==null||input.objects().isEmpty()||input.objects().size()>100||input.objects().stream().anyMatch(Objects::isNull))throw new IllegalArgumentException("请选择 1 至 100 个对象");List<Result> result=new ArrayList<>();for(var item:input.objects()){try{var fields=metadata.fields(item.identity());long id=store.register(item.directoryId(),item.identity(),item.name(),item.description(),fields);audit.success(auth,"object.register","data_object",id);result.add(new Result(item.identity(),true,id,null));}catch(Exception e){String message=e instanceof IllegalArgumentException||e instanceof IllegalStateException?e.getMessage():"无法读取或保存对象元数据";audit.failure(auth,"object.register","data_object","request",message);result.add(new Result(item.identity(),false,null,message));}}return List.copyOf(result);}
    @PostMapping("/api/data-object-operations/create-preview") public ObjectExecutionService.Preview previewCreate(@RequestBody ObjectExecutionService.CreateRequest request,Authentication auth){require(auth,"datasource.source.read");require(auth,"datasource.source.test");try{return execution.previewCreate(request);}catch(IllegalArgumentException|IllegalStateException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"无法读取目标数据库，请检查连接");}}
    @PostMapping("/api/data-object-operations/{id}/execute") public ObjectExecutionService.Preview executeCreate(@PathVariable String id,Authentication auth){require(auth,"datasource.source.read");require(auth,"datasource.source.test");try{var result=execution.executeCreate(id);if("SUCCEEDED".equals(result.status()))audit.success(auth,"object.create_table","data_object",id);else audit.failure(auth,"object.create_table","data_object",id,"执行状态："+result.status());return result;}catch(IllegalArgumentException|IllegalStateException e){audit.failure(auth,"object.create_table","data_object",id,e.getMessage());throw e;}catch(Exception e){audit.failure(auth,"object.create_table","data_object",id,"执行失败");throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"操作失败，请检查执行状态");}}
    @DeleteMapping("/api/data-object-operations/{id}") public void cancel(@PathVariable String id){execution.cancel(id);}
    @GetMapping("/api/data-object-operations") public List<ObjectExecutionService.Preview> operations(Authentication auth){require(auth,"datasource.source.read");return execution.pending();}
    @PostMapping("/api/data-object-operations/{id}/resolve-absent") public void resolveAbsent(@PathVariable String id,Authentication auth){require(auth,"datasource.source.read");require(auth,"datasource.source.test");try{execution.resolveAbsent(id);audit.success(auth,"object.create_table","data_object",id,"核对目标表不存在");}catch(IllegalArgumentException|IllegalStateException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"无法核对目标表，请检查连接");}}
    @PostMapping("/api/data-object-operations/{id}/recover") public ObjectExecutionService.Preview recover(@PathVariable String id,Authentication auth){require(auth,"datasource.source.read");require(auth,"datasource.source.test");require(auth,"datasource.object.register");try{var result=execution.recoverCreate(id);audit.success(auth,"object.register","data_object",id,"恢复登记");return result;}catch(IllegalArgumentException|IllegalStateException e){audit.failure(auth,"object.register","data_object",id,e.getMessage());throw e;}catch(Exception e){audit.failure(auth,"object.register","data_object",id,"无法核对物理表");throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"无法核对物理表，请检查连接");}}
    @PostMapping("/api/data-objects/{id}/schema-preview") public ObjectSchemaService.Plan schemaPreview(@PathVariable long id,@RequestBody ObjectSchemaService.Request request,Authentication auth){require(auth,"datasource.source.read");require(auth,"datasource.source.test");try{return schema.preview(id,request);}catch(IllegalArgumentException|IllegalStateException e){audit.failure(auth,"object.publish_schema","data_object",Long.toString(id),e.getMessage());throw e;}catch(Exception e){audit.failure(auth,"object.publish_schema","data_object",Long.toString(id),"无法读取物理表结构");throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"无法读取物理表结构");}}
    @PostMapping("/api/data-object-schema-operations/{id}/execute") public ObjectSchemaService.Plan schemaExecute(@PathVariable String id,Authentication auth){require(auth,"datasource.source.read");require(auth,"datasource.source.test");try{var result=schema.execute(id);if("SUCCEEDED".equals(result.status()))audit.success(auth,"object.publish_schema","data_object",id);else audit.failure(auth,"object.publish_schema","data_object",id,"执行状态："+result.status());return result;}catch(IllegalArgumentException|IllegalStateException e){audit.failure(auth,"object.publish_schema","data_object",id,e.getMessage());throw e;}catch(Exception e){audit.failure(auth,"object.publish_schema","data_object",id,"执行失败");throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"结构发布失败，请核对操作状态");}}
    @GetMapping("/api/data-object-schema-operations") public List<ObjectSchemaService.PendingOperation> schemaOperations(){return schema.pending();}
    @GetMapping("/api/data-object-schema-operations/{id}/actual") public List<ObjectStore.Field> schemaActual(@PathVariable String id,Authentication auth){require(auth,"datasource.source.read");require(auth,"datasource.source.test");try{return schema.inspect(id);}catch(IllegalArgumentException|IllegalStateException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"无法读取物理表结构");}}
    @PostMapping("/api/data-object-schema-operations/{id}/acknowledge") public void schemaAcknowledge(@PathVariable String id,Authentication auth){require(auth,"datasource.source.read");require(auth,"datasource.source.test");try{schema.acknowledge(id);audit.success(auth,"object.publish_schema","data_object",id,"已核对实际结构");}catch(IllegalArgumentException|IllegalStateException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"无法读取物理表结构");}}
    @DeleteMapping("/api/data-object-schema-operations/{id}") public void schemaCancel(@PathVariable String id){schema.cancel(id);}
    @ExceptionHandler(IllegalArgumentException.class) public ResponseEntity<Map<String,String>> invalid(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));}
    @ExceptionHandler(IllegalStateException.class) public ResponseEntity<Map<String,String>> conflict(IllegalStateException e){return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error",e.getMessage()));}
}
